/* Proactive Air Quality Agent: 60 s vertical launch video. 1080 x 1920, safe zone x 90-990, y 240-1680.
   One accent: orange means "the agent speaks". Grey means "stayed quiet". EPA colours only inside charts. */
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-400-normal.woff2") format("woff2"); font-weight: 400; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-500-normal.woff2") format("woff2"); font-weight: 500; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-600-normal.woff2") format("woff2"); font-weight: 600; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-700-normal.woff2") format("woff2"); font-weight: 700; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-800-normal.woff2") format("woff2"); font-weight: 800; }

:root {
  --bg: #0b0d10;
  --ink: #f4f4f5;
  --muted: #8e8e93;
  --dim: #48484a;
  --line: #2c2c2e;
  --card: #1c1c1e;
  --accent: #ff7a1a;
  --accent-soft: rgba(255, 122, 26, 0.18);
  --held: #64a8ff;
  --good: #00e400;
  --moderate: #ffff00;
  --usg: #ff7e00;
  --unhealthy: #ff3b30;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 1080px; height: 1920px; overflow: hidden; background: var(--bg); }
#root {
  position: relative; width: 100%; height: 100%; overflow: hidden;
  font-family: "Inter", sans-serif; color: var(--ink);
  -webkit-font-smoothing: antialiased; font-feature-settings: "ss01", "cv11";
}
.bg { position: absolute; inset: 0; background: radial-gradient(120% 80% at 50% 40%, #12161c 0%, var(--bg) 60%, #050607 100%); }
.vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(130% 90% at 50% 50%, transparent 55%, rgba(0, 0, 0, 0.55) 100%); }
.scene { width: 100%; height: 100%; overflow: hidden; }

/* ---------- type ---------- */
.headline { position: absolute; left: 90px; right: 90px; font-weight: 800; font-size: 92px; line-height: 1.02; letter-spacing: -0.035em; }
.headline.top { top: 250px; }
.headline .line { display: block; }
.headline .sub { margin-top: 22px; font-weight: 600; font-size: 60px; letter-spacing: -0.025em; color: var(--muted); }
