.pill.alarm { background: var(--accent); color: #111; }
.pill.calm { background: #1f3a24; color: #7ee28a; }
.marker { position: absolute; top: -40px; bottom: -30px; width: 4px; margin-left: -2px; background: var(--ink); border-radius: 2px; transform-origin: top center; }
.marker-label { position: absolute; top: -96px; transform: translateX(-50%); font-size: 30px; font-weight: 700; white-space: nowrap; }

