.s06-head { position: absolute; left: 90px; right: 90px; top: 240px; display: flex; flex-direction: column; align-items: center; gap: 30px; }
.chips { position: relative; width: 900px; height: 46px; }
.chips img { width: 100%; height: 100%; display: block; }
.tap { position: absolute; width: 90px; height: 90px; margin: -45px 0 0 -45px; border-radius: 50%; border: 5px solid rgba(255, 255, 255, 0.9); opacity: 0; }
.watch-wrap.hero { width: 640px; height: 782px; margin-left: -320px; top: 470px; }
.glow { position: absolute; inset: -60px; border-radius: 160px; background: radial-gradient(closest-side, rgba(255, 122, 26, 0.55), transparent); opacity: 0; }
