.dl.held .code { background: #13284a; color: var(--held); }
.dl.sent .code { background: var(--accent); color: #111; }
.captions { position: absolute; left: 90px; right: 90px; top: 1400px; height: 280px; }
.cap { position: absolute; left: 0; right: 0; top: 0; text-align: center; font-size: 62px; font-weight: 800; letter-spacing: -0.03em; line-height: 1.08; opacity: 0; }
