.rate .track { position: absolute; left: 0; right: 140px; top: 52px; height: 36px; }
.rate .bar { position: absolute; left: 0; top: 0; height: 36px; border-radius: 9px; background: var(--accent); transform-origin: left center; }
.rate .num { position: absolute; right: 0; top: 44px; width: 130px; text-align: right; font-size: 44px; font-weight: 800; font-variant-numeric: tabular-nums; }
.proof-note.left { max-width: 820px; }
.trend { display: block; width: 900px; height: 340px; margin-top: 50px; }
.trend path, .trend line { fill: none; stroke-linecap: round; stroke-linejoin: round; }
#s07-flat { stroke: var(--muted); stroke-width: 12; }
#s07-x1, #s07-x2 { stroke: var(--unhealthy); stroke-width: 14; }
#s07-rise { stroke: var(--accent); stroke-width: 14; }

