.log-cam { position: absolute; left: 90px; right: 90px; top: 600px; height: 1080px; transform-origin: 50% 50%; }
.log { position: absolute; inset: 0; display: flex; flex-direction: column; gap: 10px; }
.lrow { display: flex; align-items: center; gap: 20px; height: 56px; padding: 0 20px; border-radius: 14px; background: #15171b; opacity: 0; }
.lrow .t { width: 92px; font-size: 28px; font-weight: 700; color: #c7c7cc; font-variant-numeric: tabular-nums; }
.lrow .dot { width: 18px; height: 18px; border-radius: 50%; background: var(--dim); flex: none; }
.lrow .o { width: 150px; font-size: 26px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: 0.03em; }
.lrow .c { font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 24px; color: #aeaeb2; }
.lrow.held .dot { background: var(--held); } .lrow.held .o, .lrow.held .c { color: var(--held); }
.lrow.sent .dot { background: var(--accent); } .lrow.sent .o, .lrow.sent .c { color: var(--accent); }
.lrow.suppressed .dot { background: #8e8e93; }
.lrow.focus { background: #2a1a0e; box-shadow: 0 0 0 3px var(--accent); }
.trace { position: absolute; left: 90px; right: 90px; top: 1270px; display: flex; flex-direction: column; gap: 22px; }
.tl { font-size: 40px; font-weight: 600; line-height: 1.2; opacity: 0; padding: 22px 28px; border-radius: 20px; background: rgba(28, 28, 30, 0.95); border-left: 8px solid var(--accent); }
