.layers { position: absolute; left: 90px; right: 90px; top: 640px; display: flex; flex-direction: column; gap: 22px; }
.plane { display: flex; align-items: center; gap: 16px; }
.plane .pn { width: 230px; font-size: 26px; font-weight: 700; color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; }
.plane .tiles { flex: 1; display: flex; gap: 14px; flex-wrap: wrap; }
.tile { position: relative; width: 140px; height: 96px; border-radius: 18px; border: 3px solid #d1d1d6; display: grid; place-items: center; font-size: 34px; font-weight: 800; opacity: 0; }
.tile.stub.on { border-color: #ffb340; color: #ffb340; background: rgba(255, 179, 64, 0.12); }
.tile.none { border-style: dashed; border-color: var(--dim); color: var(--dim); }
.badge { position: absolute; right: -22px; top: -26px; width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; background: var(--accent); opacity: 0; }
.badge svg { width: 36px; height: 36px; fill: none; stroke: #111; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.legend { position: absolute; left: 90px; right: 90px; top: 1560px; display: flex; gap: 36px; font-size: 28px; font-weight: 600; color: var(--muted); }
.lg::before { content: ""; display: inline-block; width: 26px; height: 18px; border-radius: 5px; margin-right: 10px; vertical-align: -2px; border: 3px solid #d1d1d6; }
.lg.stub::before { border-color: #ffb340; background: rgba(255, 179, 64, 0.2); }
.lg.none::before { border-style: dashed; border-color: var(--dim); }

/* ---------- 10 · end ---------- */
.end { position: absolute; left: 90px; right: 90px; top: 0; bottom: 0; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; }
.end-line { font-size: 130px; font-weight: 800; letter-spacing: -0.05em; line-height: 1.05; opacity: 0; }
.end-brand { margin-top: 120px; opacity: 0; }
.repo { margin-top: 18px; font-size: 32px; color: var(--muted); font-family: ui-monospace, "SF Mono", Menlo, monospace; }
.fade-black { position: absolute; inset: 0; background: #000; opacity: 0; }

